<template><div class="page"><div class="section-title"><div><h2>告警中心</h2><span class="muted">Prometheus 当前活跃告警</span></div><div style="display:flex;gap:10px"><n-select v-model:value="severity" clearable placeholder="严重级别" :options="severityOptions" style="width:150px"/><n-button type="primary" @click="load">刷新</n-button></div></div><div class="panel"><n-data-table :columns="columns" :data="filtered" :loading="loading" :pagination="{pageSize:10}"/></div><n-drawer v-model:show="show" :width="460"><n-drawer-content v-if="selected" :title="selected.alert_name"><n-space vertical><n-tag :type="severityType(selected.severity)">{{selected.severity}}</n-tag><n-descriptions bordered :column="1"><n-descriptions-item label="状态">{{selected.state}}</n-descriptions-item><n-descriptions-item label="持续时间">{{selected.duration}}</n-descriptions-item><n-descriptions-item label="激活时间">{{selected.active_at}}</n-descriptions-item><n-descriptions-item label="描述">{{selected.description||'暂无描述'}}</n-descriptions-item></n-descriptions><n-button type="primary" @click="router.push({path:'/app/chat',query:{prompt:`分析告警 ${selected.alert_name}`}})">让 Agent 分析</n-button></n-space></n-drawer-content></n-drawer></div></template>
<script setup>import {h,ref,computed,onMounted} from 'vue';import {useRouter} from 'vue-router';import {alertsApi} from '@/api';const router=useRouter(),alerts=ref([]),loading=ref(false),severity=ref(null),show=ref(false),selected=ref(null),severityOptions=[{label:'Critical',value:'critical'},{label:'Warning',value:'warning'},{label:'Info',value:'info'}];const filtered=computed(()=>severity.value?alerts.value.filter(a=>a.severity===severity.value):alerts.value);const severityType=s=>s==='critical'?'error':s==='warning'?'warning':'info';const columns=[{title:'告警名称',key:'alert_name'},{title:'严重级别',key:'severity',render:r=>h('span',{class:`alert-${r.severity}`},r.severity)},{title:'状态',key:'state'},{title:'描述',key:'description',ellipsis:{tooltip:true}},{title:'持续时间',key:'duration'},{title:'操作',key:'action',render:r=>h('button',{class:'link-button',onClick:()=>{selected.value=r;show.value=true}},'详情')}];async function load(){loading.value=true;try{const r=await alertsApi.list();alerts.value=r.alerts||[]}finally{loading.value=false}}onMounted(load)</script>
